-- ── 5. Constancia en la tabla `migrations` ──────────────────
-- Sin esto, un `php artisan migrate` posterior intentaría crear
-- las tablas de nuevo. El batch se calcula solo.
--
-- No se usa INSERT IGNORE porque `migrations` no tiene índice único
-- sobre `migration`: IGNORE no evitaría el duplicado. El LEFT JOIN sí.
SET @batch := (SELECT COALESCE(MAX(`batch`), 0) + 1 FROM `migrations`);

SELECT nuevas.`m`, @batch
FROM (
          SELECT '2026_09_23_000001_create_servicios_table'     AS `m`
    UNION SELECT '2026_09_23_000002_create_equivalencias_table'
    UNION SELECT '2026_09_24_000001_create_sitios_table'
) AS nuevas
LEFT JOIN (SELECT `migration` FROM `migrations`) AS ya
       ON ya.`migration` = nuevas.`m`
WHERE ya.`migration` IS NULL;

SET FOREIGN_KEY_CHECKS = 1;

